// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer signer;
    FakeToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        signer = new Signer();
        token = new FakeToken();
    }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));

        address[] memory empty = new address[](0);
        PuttyV2.ERC20Asset[] memory noErc20 = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory noErc721 = new PuttyV2.ERC721Asset[](0);
        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(signer),
            isCall: false,
            isLong: false,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1000,
            nonce: 0,
            whitelist: empty,
            floorTokens: empty,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        uint256[] memory noFloorIds = new uint256[](0);
        uint256 positionId = c.fillOrder(order, hex"", noFloorIds);

        // first transfer by the owner (this test contract) succeeds on both versions
        c.transferFrom(address(this), recipient, positionId);

        // general rule: after a successful transfer, the ORIGINAL owner can no longer
        // transferFrom the token; it must revert (ownership left with recipient).
        bool ok;
        try c.transferFrom(address(this), recipient, positionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "original owner must not be able to transfer an already-transferred token");
    }
}

contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
